// body-sha256: 691b0d9b460286cabee432696cfedeb3fe0b1898d9debc66984ae56b5982d316
import { test } from '../support/core/fixtures';

test.use({ preconditions: ['empty-cart', 'guest', 'no-geolocation'], priceSource: 'ui', reserved: ['Wood Saw'] });

test('Wood Saw and two units of another product, raise the saw to three, remove the other; total checked after each step', async ({ shopper }) => {
  const a = await shopper.add({ pick: 'by-name', name: 'Wood Saw' }, 1);
  await shopper.checkTotal('S1');

  const b = await shopper.add({ pick: 'first-available', filters: { needQty: 2 } }, 2);
  await shopper.checkTotal('S2');

  await shopper.setQuantity(a, 3);
  await shopper.checkTotal('S3');

  await shopper.remove(b);
  await shopper.checkTotal('S4');
});
